// Shared contract for the native Nxeon mail client (/dashboard/mail).
// Both the IMAP/SMTP backend (lib/mail/*, lib/actions-mail.ts) and the UI
// (components/customer/mail/*, app/dashboard/mail) build against these types so
// they can't drift. The client connects to the customer's own mailbox on the
// self-hosted mail server (10.20.0.10) over IMAP (993) / SMTP submission (587),
// authenticating with the mailbox's stored (encrypted) credential.

export const MAIL_IMAP_HOST = process.env.MAIL_IMAP_HOST || "10.20.0.10";
export const MAIL_IMAP_PORT = Number(process.env.MAIL_IMAP_PORT || 993);
export const MAIL_SMTP_HOST = process.env.MAIL_SMTP_HOST || "10.20.0.10";
export const MAIL_SMTP_PORT = Number(process.env.MAIL_SMTP_PORT || 587);

export type MailFolderRole =
  | "inbox" | "sent" | "drafts" | "trash" | "junk" | "archive" | "custom";

export type MailFolder = {
  path: string; // IMAP path, e.g. "INBOX", "Sent"
  name: string; // display name
  role: MailFolderRole;
  unread: number;
  total: number;
};

export type MailAddress = { name?: string; address: string };

export type MessageSummary = {
  uid: number;
  folder: string;
  from: MailAddress;
  to: MailAddress[];
  subject: string;
  preview: string; // short text snippet of the body
  date: string; // ISO
  seen: boolean;
  flagged: boolean; // starred
  answered: boolean;
  hasAttachments: boolean;
};

export type MessageAttachment = {
  id: string; // opaque id for the download route (e.g. "<uid>:<partId>")
  filename: string;
  mime: string;
  sizeBytes: number;
};

export type MessageFull = MessageSummary & {
  cc: MailAddress[];
  html: string | null; // SANITIZED html body (must be sanitized server-side)
  text: string | null;
  attachments: MessageAttachment[];
};

export type MailboxInfo = {
  address: string;
  usedBytes: number;
  quotaBytes: number;
};

export type ListResult = {
  messages: MessageSummary[];
  total: number;
  page: number;
  pageSize: number;
};

export type SendPayload = {
  to: string; // comma-separated
  cc?: string;
  bcc?: string;
  subject: string;
  text?: string;
  html?: string;
  inReplyToUid?: number; // for replies (sets In-Reply-To / References)
  replyFolder?: string; // folder of the message being replied to
};
