  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
     text automatically. Default = the dark theme's light text. */
  :root {
    --fg: #ffffff;
    --fg-muted: #94a3b8; /* slate-400 */
  }

  /* "light" tone — a rare, deliberate light band to break up the dark theme and
     divide long pages (used sparingly, ~one per page). Flips the foreground
     tokens to dark and restyles surfaces/buttons inside so everything stays
     legible without touching each call site. */
  .tone-light {
    @apply border-y border-slate-200/70 text-slate-700;
    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
    --fg: #0f172a;       /* slate-900 */
