import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, Badge } from "@/components/ui/primitives";
import {
  EmailHosting,
  type PlanOpt,
  type SubscriptionRow,
} from "@/components/customer/EmailHosting";

export const dynamic = "force-dynamic";

export default async function EmailHostingPage() {
  const user = await requireUser();

  const [domains, plans, subscriptions] = await Promise.all([
    db.domain.findMany({
      where: { userId: user.id, status: "ACTIVE" },
      orderBy: { name: "asc" },
    }),
    db.emailPlan.findMany({
      where: { active: true },
      orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
    }),
    db.emailSubscription.findMany({
      where: { userId: user.id, status: { not: "CANCELLED" } },
      include: { emailPlan: true, mailboxes: { orderBy: { createdAt: "asc" } } },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const planOpts: PlanOpt[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    mailboxes: p.mailboxes,
    storageGB: p.storageGB,
    priceCents: p.priceCents,
    termMonths: p.termMonths,
  }));

  const subRows: SubscriptionRow[] = subscriptions.map((s) => ({
    id: s.id,
    domainName: s.domainName,
    status: s.status,
    external: s.external,
    verified: s.verified,
    planName: s.emailPlan.name,
    planMailboxes: s.emailPlan.mailboxes,
    planStorageGB: s.emailPlan.storageGB,
    expiresAt: s.expiresAt ? s.expiresAt.toISOString() : null,
    mailboxes: s.mailboxes.map((m) => ({
      id: m.id,
      address: m.address,
      createdAt: m.createdAt.toISOString(),
    })),
  }));

  return (
    <div>
      <PageHeader
        title="Business Email"
        sub="Professional mailboxes on your own domain (you@yourdomain.com)."
      >
        <Badge tone="brand">{subRows.length} subscription{subRows.length === 1 ? "" : "s"}</Badge>
      </PageHeader>

      <EmailHosting
        domains={domains.map((d) => d.name)}
        plans={planOpts}
        subscriptions={subRows}
        balanceCents={user.balanceCents}
      />
    </div>
  );
}
