import type { MailAddress } from "@/lib/mail/types";

/* -------------------------------------------------------------------------- */
/* Presentation helpers shared across the mail UI                              */
/* -------------------------------------------------------------------------- */

/** Display name for an address: prefer the friendly name, fall back to the
 *  local part of the email (before the @). */
export function displayName(a?: MailAddress | null): string {
  if (!a) return "Unknown";
  if (a.name && a.name.trim()) return a.name.trim();
  const at = a.address.indexOf("@");
  return at > 0 ? a.address.slice(0, at) : a.address || "Unknown";
}

/** Up-to-two-letter initials from a name or address. */
export function initials(a?: MailAddress | null): string {
  const name = displayName(a);
  const parts = name.replace(/[^\p{L}\p{N} ]/gu, " ").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/** Deterministic on-brand gradient for an avatar, derived from the address so a
 *  given sender always gets the same colour. Hues are pulled toward the violet /
 *  blue / cyan Nxeon range with a couple of warm accents for variety. */
const AVATAR_GRADIENTS = [
  "from-brand-500 to-accent-blue",
  "from-accent-blue to-brand-400",
  "from-brand-400 to-fuchsia-500",
  "from-accent-cyan to-accent-blue",
  "from-violet-500 to-brand-600",
  "from-sky-500 to-brand-500",
  "from-brand-600 to-violet-400",
  "from-emerald-500 to-accent-cyan",
  "from-rose-500 to-brand-500",
  "from-amber-500 to-rose-500",
];

export function avatarGradient(seed: string): string {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return AVATAR_GRADIENTS[h % AVATAR_GRADIENTS.length];
}

/** Compact list timestamp: time for today, "Mon" for this week, else a short date. */
export function shortDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const now = new Date();
  const sameDay =
    d.getFullYear() === now.getFullYear() &&
    d.getMonth() === now.getMonth() &&
    d.getDate() === now.getDate();
  if (sameDay) return d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  const diffDays = (now.getTime() - d.getTime()) / 86_400_000;
  if (diffDays < 7 && diffDays > 0) return d.toLocaleDateString([], { weekday: "short" });
  const sameYear = d.getFullYear() === now.getFullYear();
  return d.toLocaleDateString([], sameYear ? { month: "short", day: "numeric" } : { month: "short", day: "numeric", year: "2-digit" });
}

/** Verbose header timestamp for the reading pane. */
export function fullDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString([], {
    weekday: "short",
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

export function fmtBytesShort(b: number): string {
  if (!b || b <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
  return `${(b / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}

/** Format a list of addresses as "Alice, Bob +2". */
export function joinAddresses(list: MailAddress[], max = 3): string {
  if (!list || list.length === 0) return "—";
  const names = list.slice(0, max).map(displayName);
  const extra = list.length - max;
  return names.join(", ") + (extra > 0 ? ` +${extra}` : "");
}

/* -------------------------------------------------------------------------- */
/* Client-side category heuristics (Primary / Promotions / Social tabs)        */
/* -------------------------------------------------------------------------- */

export type MailTab = "primary" | "promotions" | "social";

const PROMO_RE = /(newsletter|deal|sale|% off|unsubscribe|promo|offer|coupon|discount|marketing|no-?reply|noreply|billing|receipt|invoice|order)/i;
const SOCIAL_DOMAINS = /(facebook|instagram|twitter|x\.com|linkedin|github|reddit|discord|slack|notifications?|youtube|tiktok|pinterest|medium)/i;

export function categoryOf(from: MailAddress, subject: string): MailTab {
  const hay = `${from.address} ${from.name ?? ""} ${subject}`;
  if (SOCIAL_DOMAINS.test(from.address) || SOCIAL_DOMAINS.test(from.name ?? "")) return "social";
  if (PROMO_RE.test(hay)) return "promotions";
  return "primary";
}

