export type IconName = keyof typeof Icon;

"use client";

import type { MailboxInfo } from "@/lib/mail/types";
import { Icon, type IconName, fmtBytesShort } from "./util";

export type RailItem = {
  key: string; // folder path or virtual sentinel
  label: string;
  icon: IconName;
  unread?: number;
  virtual?: boolean;
};

export function FolderRail({
  primary,
  custom,
  selected,
  mailbox,
  onSelect,
  onCompose,
  onRefresh,
  refreshing,
}: {
  primary: RailItem[];
  custom: RailItem[];
  selected: string;
  mailbox: MailboxInfo | null;
  onSelect: (key: string) => void;
  onCompose: () => void;
  onRefresh: () => void;
  refreshing: boolean;
}) {
  const usedPct = mailbox && mailbox.quotaBytes > 0
    ? Math.min(100, Math.round((mailbox.usedBytes / mailbox.quotaBytes) * 100))
    : 0;
  const nearFull = usedPct >= 85;

  return (
    <div className="flex h-full flex-col">
      {/* Compose */}
      <div className="p-3">
        <button onClick={onCompose} className="btn-primary w-full">
          <Icon.compose size={16} />
          Compose
        </button>
      </div>

      <nav className="flex-1 space-y-1 overflow-y-auto px-2 pb-3">
        {primary.map((it) => (
          <RailButton key={it.key} item={it} active={selected === it.key} onClick={() => onSelect(it.key)} />
        ))}

        {custom.length > 0 && (
          <>
            <p className="section-label px-3 pb-1 pt-4">Folders</p>
            {custom.map((it) => (
              <RailButton key={it.key} item={it} active={selected === it.key} onClick={() => onSelect(it.key)} />
            ))}
          </>
        )}

        <p className="section-label px-3 pb-1 pt-4">Tools</p>
        <button
          onClick={onRefresh}
          className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white"
        >
          <Icon.refresh size={17} className={refreshing ? "animate-spin text-brand-300" : ""} />
          Refresh
        </button>
        <a
          href="/dashboard/email"
          className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white"
        >
          <Icon.cog size={17} />
          Mail settings
        </a>
        <button
          disabled
          title="Filters — coming soon"
          className="flex w-full cursor-not-allowed items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-600"
        >
          <Icon.filter size={17} />
          Filters
        </button>
      </nav>

      {/* Storage bar */}
      <div className="border-t border-white/[0.06] p-3">
        <div className="mb-1.5 flex items-center justify-between text-[11px]">
          <span className="font-medium text-slate-400">Storage</span>
          <span className={nearFull ? "text-amber-300" : "text-slate-500"}>
            {mailbox ? `${fmtBytesShort(mailbox.usedBytes)} / ${fmtBytesShort(mailbox.quotaBytes)}` : "—"}
          </span>
        </div>
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className={`h-full rounded-full transition-all ${nearFull ? "bg-gradient-to-r from-amber-400 to-red-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
            style={{ width: `${usedPct}%` }}
          />
        </div>
        {mailbox && (
          <p className="mt-1.5 truncate text-[11px] text-slate-600" title={mailbox.address}>
            {mailbox.address}
          </p>
        )}
      </div>
    </div>
  );
}

function RailButton({ item, active, onClick }: { item: RailItem; active: boolean; onClick: () => void }) {
  const Ico = Icon[item.icon];
  return (
    <button
      onClick={onClick}
      className={`flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium transition-colors ${
        active ? "nav-item-active" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
      }`}
    >
      <Ico size={17} className={active ? "text-white" : ""} />
      <span className="flex-1 truncate text-left">{item.label}</span>
      {item.unread ? (
        <span
          className={`flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1.5 text-[10px] font-semibold ${
            active ? "bg-white/25 text-white" : "bg-brand-500/90 text-white"
          }`}
        >
          {item.unread > 99 ? "99+" : item.unread}
        </span>
      ) : null}
    </button>
  );
}

"use client";

import type { MessageSummary } from "@/lib/mail/types";
import {
  Icon,
  initials,
  displayName,
  avatarGradient,
  shortDate,
  categoryOf,
  type MailTab,
} from "./util";

const TABS: { key: MailTab; label: string }[] = [
  { key: "primary", label: "Primary" },
  { key: "promotions", label: "Promotions" },
  { key: "social", label: "Social" },
];

export function MessageList({
  title,
  unread,
  messages,
  total,
  page,
  pageSize,
  loading,
  selectedUid,
  tab,
  search,
  onTab,
  onSearch,
  onSelect,
  onToggleStar,
  onPage,
}: {
  title: string;
  unread: number;
  messages: MessageSummary[];
  total: number;
  page: number;
  pageSize: number;
  loading: boolean;
  selectedUid: number | null;
  tab: MailTab;
  search: string;
  onTab: (t: MailTab) => void;
  onSearch: (s: string) => void;
  onSelect: (m: MessageSummary) => void;
  onToggleStar: (m: MessageSummary) => void;
  onPage: (p: number) => void;
}) {
  const filtered = messages.filter((m) => categoryOf(m.from, m.subject) === tab);
  const totalPages = Math.max(1, Math.ceil(total / (pageSize || 25)));
  const start = total === 0 ? 0 : (page - 1) * (pageSize || 25) + 1;
  const end = Math.min(total, page * (pageSize || 25));

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="border-b border-white/[0.06] px-4 pb-3 pt-4">
        <div className="flex items-center gap-2">
          <h2 className="text-lg font-bold tracking-tight">{title}</h2>
          {unread > 0 && (
            <span className="rounded-full bg-brand-500/15 px-2 py-0.5 text-xs font-semibold text-brand-300">
              {unread} unread
            </span>
          )}
        </div>

        {/* Search */}
        <div className="mt-3">
          <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-navy-900/80 px-3 py-2 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
            <span className="text-slate-500">
              <Icon.search size={15} />
            </span>
            <input
              value={search}
              onChange={(e) => onSearch(e.target.value)}
              placeholder="Search mail…"
              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-500"
            />
            {search && (
              <button onClick={() => onSearch("")} className="text-slate-500 hover:text-white">
                <Icon.close size={14} />
              </button>
            )}
          </div>
        </div>

        {/* Category tabs */}
        <div className="mt-3 flex gap-1">
          {TABS.map((t) => (
            <button
              key={t.key}
              onClick={() => onTab(t.key)}
              className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors ${
                tab === t.key
                  ? "bg-white/[0.08] text-white"
                  : "text-slate-400 hover:bg-white/[0.04] hover:text-slate-200"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* Rows */}
      <div className="flex-1 overflow-y-auto">
        {loading ? (
          <ListSkeleton />
        ) : filtered.length === 0 ? (
          <Empty search={search} tab={tab} hadMessages={messages.length > 0} />
        ) : (
          <ul>
            {filtered.map((m) => (
              <Row
                key={m.uid}
                m={m}
                active={selectedUid === m.uid}
                onSelect={() => onSelect(m)}
                onToggleStar={() => onToggleStar(m)}
              />
            ))}
          </ul>
        )}
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between border-t border-white/[0.06] px-4 py-2.5 text-xs text-slate-500">
        <span>{total === 0 ? "No messages" : `${start}–${end} of ${total}`}</span>
        <div className="flex items-center gap-1">
          <button
            disabled={page <= 1 || loading}
            onClick={() => onPage(page - 1)}
            className="btn-ghost rounded-lg p-1.5 disabled:opacity-30"
            aria-label="Previous page"
          >
            <Icon.chevronLeft size={16} />
          </button>
          <span className="px-1 tabular-nums">
            {page} / {totalPages}
          </span>
          <button
            disabled={page >= totalPages || loading}
            onClick={() => onPage(page + 1)}
            className="btn-ghost rounded-lg p-1.5 disabled:opacity-30"
            aria-label="Next page"
          >
            <Icon.chevronRight size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}

function Row({
  m,
  active,
  onSelect,
  onToggleStar,
}: {
  m: MessageSummary;
  active: boolean;
  onSelect: () => void;
  onToggleStar: () => void;
}) {
  return (
    <li
      onClick={onSelect}
      className={`group relative flex cursor-pointer gap-3 border-b border-white/[0.04] px-4 py-3 transition-colors ${
        active ? "bg-brand-500/10" : "hover:bg-white/[0.03]"
      }`}
    >
      {active && <span className="absolute inset-y-0 left-0 w-0.5 bg-gradient-to-b from-accent-blue to-brand-500" />}

      {/* Avatar */}
      <div
        className={`flex h-9 w-9 flex-none items-center justify-center rounded-full bg-gradient-to-br text-[13px] font-bold text-white ${avatarGradient(
          m.from.address
        )}`}
      >
        {initials(m.from)}
      </div>

      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          {!m.seen && <span className="h-2 w-2 flex-none rounded-full bg-brand-400" />}
          <span className={`min-w-0 flex-1 truncate text-sm ${m.seen ? "text-slate-300" : "font-semibold text-white"}`}>
            {displayName(m.from)}
          </span>
          <span className="flex-none text-[11px] text-slate-500">{shortDate(m.date)}</span>
        </div>
        <p className={`mt-0.5 truncate text-[13px] ${m.seen ? "text-slate-400" : "font-medium text-slate-200"}`}>
          {m.subject || "(no subject)"}
        </p>
        <div className="mt-0.5 flex items-center gap-1.5">
          {m.hasAttachments && (
            <span className="flex-none text-slate-500">
              <Icon.paperclip size={12} />
            </span>
          )}
          <p className="truncate text-xs text-slate-500">{m.preview || " "}</p>
        </div>
      </div>

      {/* Star */}
      <button
        onClick={(e) => {
          e.stopPropagation();
          onToggleStar();
        }}
        className={`flex-none self-start rounded-md p-1 transition-colors ${
          m.flagged ? "text-amber-400" : "text-slate-600 opacity-0 hover:text-amber-300 group-hover:opacity-100"
        }`}
        aria-label={m.flagged ? "Unstar" : "Star"}
      >
        {m.flagged ? <Icon.starFilled size={15} /> : <Icon.star size={15} />}
      </button>
    </li>
  );
}

function ListSkeleton() {
  return (
    <ul className="space-y-px">
      {Array.from({ length: 8 }).map((_, i) => (
        <li key={i} className="flex gap-3 px-4 py-3">
          <div className="skeleton h-9 w-9 flex-none rounded-full" />
          <div className="flex-1 space-y-2 py-0.5">
            <div className="skeleton h-3 w-1/3" />
            <div className="skeleton h-3 w-2/3" />
            <div className="skeleton h-2.5 w-1/2" />
          </div>
        </li>
      ))}
    </ul>
  );
}

function Empty({ search, tab, hadMessages }: { search: string; tab: MailTab; hadMessages: boolean }) {
  return (
    <div className="flex h-full flex-col items-center justify-center px-6 py-16 text-center">
      <div className="mb-3 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-3.5 text-brand-300">
        <Icon.mail size={26} />
      </div>
      <p className="text-sm font-semibold text-slate-200">
        {search ? "No matches" : hadMessages ? `Nothing in ${tab}` : "No messages"}
      </p>
      <p className="mt-1 max-w-[15rem] text-xs text-slate-500">
        {search
          ? "Try a different search term."
          : hadMessages
          ? "Switch tabs to see the rest of this folder."
          : "This folder is empty. New mail will show up here."}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { MessageFull, MailFolder } from "@/lib/mail/types";
import {
  Icon,
  initials,
  displayName,
  avatarGradient,
  fullDate,
  joinAddresses,
  fmtBytesShort,
} from "./util";

export function ReadingPane({
  message,
  loading,
  folders,
  currentFolder,
  onReply,
  onReplyAll,
  onForward,
  onArchive,
  onDelete,
  onMove,
  onToggleStar,
  onQuickReply,
  onBack,
}: {
  message: MessageFull | null;
  loading: boolean;
  folders: MailFolder[];
  currentFolder: string;
  onReply: () => void;
  onReplyAll: () => void;
  onForward: () => void;
  onArchive: () => void;
  onDelete: () => void;
  onMove: (toFolder: string) => void;
  onToggleStar: () => void;
  onQuickReply: (text: string) => Promise<void>;
  onBack: () => void;
}) {
  const [moveOpen, setMoveOpen] = useState(false);
  const [quick, setQuick] = useState("");
  const [sending, setSending] = useState(false);

  useEffect(() => {
    setQuick("");
    setMoveOpen(false);
  }, [message?.uid, message?.folder]);

  if (loading) return <ReadingSkeleton onBack={onBack} />;

  if (!message) {
    return (
      <div className="flex h-full flex-col items-center justify-center px-6 text-center">
        <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-5 text-brand-300">
          <Icon.mail size={34} />
        </div>
        <p className="text-base font-semibold text-slate-200">Select a message</p>
        <p className="mt-1 max-w-xs text-sm text-slate-500">
          Pick a conversation from the list to read it here.
        </p>
      </div>
    );
  }

  const submitQuick = async () => {
    const text = quick.trim();
    if (!text || sending) return;
    setSending(true);
    try {
      await onQuickReply(text);
      setQuick("");
    } finally {
      setSending(false);
    }
  };

  const moveTargets = folders.filter((f) => f.path !== currentFolder);

  return (
    <div className="flex h-full flex-col">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-1 border-b border-white/[0.06] px-3 py-2.5">
        <button onClick={onBack} className="btn-ghost mr-1 rounded-lg p-2 lg:hidden" aria-label="Back to list">
          <Icon.chevronLeft size={18} />
        </button>
        <ToolBtn label="Archive" onClick={onArchive}><Icon.archive size={17} /></ToolBtn>
        <ToolBtn label="Delete" onClick={onDelete} danger><Icon.trash size={17} /></ToolBtn>
        <ToolBtn label="Snooze" disabled title="Snooze — coming soon"><Icon.clock size={17} /></ToolBtn>

        {/* Move dropdown */}
        <div className="relative">
          <ToolBtn label="Move" onClick={() => setMoveOpen((v) => !v)}><Icon.move size={17} /></ToolBtn>
          {moveOpen && (
            <>
              <div className="fixed inset-0 z-10" onClick={() => setMoveOpen(false)} />
              <div className="glass absolute left-0 top-11 z-20 max-h-72 w-56 overflow-y-auto py-1.5 shadow-2xl">
                <p className="section-label px-3 py-1">Move to</p>
                {moveTargets.map((f) => (
                  <button
                    key={f.path}
                    onClick={() => {
                      setMoveOpen(false);
                      onMove(f.path);
                    }}
                    className="flex w-full items-center gap-2.5 px-3 py-2 text-left text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white"
                  >
                    <Icon.folder size={15} className="text-slate-500" />
                    <span className="truncate">{f.name}</span>
                  </button>
                ))}
              </div>
            </>
          )}
        </div>

        <div className="mx-1 h-6 w-px bg-white/[0.08]" />

        <ToolBtn label="Reply" onClick={onReply}><Icon.reply size={17} /></ToolBtn>
        <ToolBtn label="Reply all" onClick={onReplyAll}><Icon.replyAll size={17} /></ToolBtn>
        <ToolBtn label="Forward" onClick={onForward}><Icon.forward size={17} /></ToolBtn>

        <button
          onClick={onToggleStar}
          className={`btn-ghost ml-auto rounded-lg p-2 ${message.flagged ? "text-amber-400" : ""}`}
          aria-label={message.flagged ? "Unstar" : "Star"}
        >
          {message.flagged ? <Icon.starFilled size={17} /> : <Icon.star size={17} />}
        </button>
      </div>

      {/* Scroll body */}
      <div className="flex-1 overflow-y-auto">
        <div className="px-5 py-5 sm:px-7">
          <h1 className="text-xl font-bold leading-snug tracking-tight text-white sm:text-2xl">
            {message.subject || "(no subject)"}
          </h1>

          {/* Sender line */}
          <div className="mt-4 flex items-start gap-3">
            <div
              className={`flex h-11 w-11 flex-none items-center justify-center rounded-full bg-gradient-to-br text-sm font-bold text-white ${avatarGradient(
                message.from.address
              )}`}
            >
              {initials(message.from)}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-baseline gap-x-2">
                <span className="text-sm font-semibold text-white">{displayName(message.from)}</span>
                <span className="truncate text-xs text-slate-500">&lt;{message.from.address}&gt;</span>
              </div>
              <p className="mt-0.5 text-xs text-slate-500">
                to {joinAddresses(message.to)}
                {message.cc.length > 0 && <>, cc {joinAddresses(message.cc)}</>}
              </p>
            </div>
            <span className="flex-none whitespace-nowrap pt-0.5 text-xs text-slate-500">
              {fullDate(message.date)}
            </span>
          </div>

          {/* Attachments */}
          {message.attachments.length > 0 && (
            <div className="mt-4 flex flex-wrap gap-2">
              {message.attachments.map((att) => (
                <a
                  key={att.id}
                  href={`/api/mail/attachment?folder=${encodeURIComponent(message.folder)}&uid=${message.uid}&part=${encodeURIComponent(att.id)}`}
                  className="group flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-sm transition-colors hover:border-brand-500/30 hover:bg-white/[0.06]"
                >
                  <span className="text-brand-300">
                    <Icon.paperclip size={16} />
                  </span>
                  <span className="min-w-0">
                    <span className="block max-w-[12rem] truncate text-slate-200 group-hover:text-white">{att.filename}</span>
                    <span className="block text-[11px] text-slate-500">{fmtBytesShort(att.sizeBytes)}</span>
                  </span>
                </a>
              ))}
            </div>
          )}

          <div className="divider" />

          {/* Body */}
          <MessageBody html={message.html} text={message.text} />
        </div>
      </div>

      {/* Quick reply */}
      <div className="border-t border-white/[0.06] bg-navy-900/40 p-3">
        <div className="flex items-end gap-2 rounded-xl border border-white/10 bg-navy-900/80 p-2 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
          <div className={`hidden h-8 w-8 flex-none items-center justify-center rounded-full bg-gradient-to-br text-xs font-bold text-white sm:flex ${avatarGradient(message.from.address)}`}>
            <Icon.reply size={15} />
          </div>
          <textarea
            value={quick}
            onChange={(e) => setQuick(e.target.value)}
            onKeyDown={(e) => {
              if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
                e.preventDefault();
                void submitQuick();
              }
            }}
            rows={1}
            placeholder={`Quick reply to ${displayName(message.from)}…`}
            className="max-h-32 min-h-[2.25rem] flex-1 resize-none bg-transparent py-1.5 text-sm text-slate-100 outline-none placeholder:text-slate-500"
          />
          <button
            onClick={submitQuick}
            disabled={!quick.trim() || sending}
            className="btn-primary flex-none px-3 py-2"
          >
            {sending ? "Sending…" : "Send"}
          </button>
        </div>
        <p className="mt-1 px-1 text-[11px] text-slate-600">
          Press <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span> to send
        </p>
      </div>
    </div>
  );
}

/** Renders the email body. HTML is dropped into a fully sandboxed iframe (no
 *  allow-scripts, no allow-same-origin) so hostile markup/scripts cannot run or
 *  reach cookies/storage. Plaintext falls back to a pre block. */
function MessageBody({ html, text }: { html: string | null; text: string | null }) {
  const ref = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(320);

  const doc = html
    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
        body{padding:16px;}
        img{max-width:100%;height:auto;}
        a{color:#5f2ee8;}
        table{max-width:100%;}
        pre{white-space:pre-wrap;}
        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
      </style></head><body>${html}</body></html>`
    : null;

  // Best-effort autosize: with sandbox="" we cannot read the inner document, so
  // grow to a comfortable default and let the iframe scroll for very tall mail.
  useEffect(() => {
    setHeight(html ? 480 : 0);
  }, [html]);

  if (doc) {
    return (
      <iframe
        ref={ref}
        sandbox=""
        srcDoc={doc}
        title="Message content"
        className="w-full rounded-xl border border-white/[0.06] bg-white"
        style={{ height }}
      />
    );
  }

  if (text && text.trim()) {
    return (
      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
        {text}
      </pre>
    );
  }

  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
}

